"use client";
/* Prompty, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Prompty(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("prompty"); }, []);
  return React.createElement("piix-sprite", { "name": "prompty", ...piixAttrs(props) });
}

export default Prompty;
